/** The Watergat Quiz Night title lockup: acacia roundel, name and strapline, set in the app's own fonts. */
@Component({
  selector: 'app-wordmark',
  imports: [Acacia],
  template: `
    <span class="roundel"><app-acacia /></span>
    <span class="words">
      <span class="kicker">Watergat</span>
      <span class="name display gold">Quiz Night</span>
      <span class="strap">Round <i>·</i> Score <i>·</i> Win</span>
    </span>
  `,
  styles: `
    /* Everything is sized in em, so the host's font-size scales the whole lockup */
    :host {
      display: inline-flex;
      align-items: center;
      gap: 0.32em;
      text-align: left;
      line-height: 1;
    }
    .roundel {
      flex: none;
      width: 1.9em;
      height: 1.9em;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: linear-gradient(90deg, #c8381c, #f7a531);
      box-shadow: 0 0.06em 0.3em rgba(0, 0, 0, 0.45);
      color: #0b0907;
    }
    .roundel app-acacia {
      width: 86%;
      margin-top: 12%;
    }
    .words {
      display: flex;
      flex-direction: column;
      filter: drop-shadow(0 0.04em 0.12em rgba(0, 0, 0, 0.6));
    }
    .kicker {
      margin-bottom: 0.3em;
      font-size: 0.3em;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.3em;
      white-space: nowrap;
      color: var(--cream-2);
    }
    .name {
      font-size: 1em;
      text-transform: uppercase;
      letter-spacing: 0.04em;
      white-space: nowrap;
      padding-bottom: 0.14em;
      border-bottom: 0.045em solid transparent;
      border-image: linear-gradient(90deg, #c8381c, #f7a531) 1;
    }
    .strap {
      margin-top: 0.5em;
      font-size: 0.27em;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.34em;
      white-space: nowrap;
      color: var(--cream-2);
    }
    .strap i {
      font-style: normal;
      color: var(--gold);
    }
  `,
})
export class Wordmark {}

/**
 * Savanna sunset artwork filling its container. Upright screens get the tall crop,
 * wide screens the 16:9 one; both are darkened where the titles sit.
 */
@Component({
  selector: 'app-backdrop',
  template: `
    <picture>
      @if (!wide()) {
        <source media="(max-aspect-ratio: 1/1)" srcset="art/hero-phone.webp" type="image/webp" />
        <source media="(max-aspect-ratio: 1/1)" srcset="art/hero-phone.jpg" />
      }
      <source srcset="art/hero-tv.webp" type="image/webp" />
      <img src="art/hero-tv.jpg" alt="" />
    </picture>
  `,
  styles: `
    :host { display: block; overflow: hidden; background: #4f1a1c; }
    img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: var(--focus, 70% 50%); }
  `,
})
export class Backdrop {
  /** Always use the 16:9 crop, e.g. in a short banner */
  readonly wide = input(false);
}
